{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO allowable rent increase","requirement":"Landlords may raise rent once every 12 months by the allowable rent increase percentage. From February 2, 2026 utility and dependent add-on increases are no longer allowed, but a 10% increase for an added non-dependent tenant remains; larger increases need LAHD approval.","key_value":"Once every 12 months at the allowable rent increase percentage; 10% for an additional tenant","coverage_conditions":"Rental properties first built on or before October 1, 1978 (apartments, condominiums, townhomes, duplexes, ADUs, JADUs, hotel rooms occupied over 30 days, mobile homes), plus replacement units under LAMC 151.28.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"replacement units under LAMC Section 151.28 are also covered"},{"type":"other","text":"luxury exemption on landlord application where the May 31, 1978 rent met the threshold"}],"per_tenancy":"Rent amounts are not regulated for condominium or townhome tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)"]},"exemptions":"Rent amount not regulated for condominium and townhome tenancies that commenced after December 31, 1995; landlords may apply for a luxury exemption based on the rent charged on or before May 31, 1978; temporary exemptions.","penalty":null,"effective_date":"2026-02-02","valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO legal reasons for eviction and no-fault relocation","requirement":"A landlord may terminate an RSO tenancy only for the listed at-fault or no-fault reasons, must file the termination notice with LAHD within three business days of serving it, and must pay tenant relocation assistance for no-fault evictions.","key_value":"3 business days to file termination notice with LAHD","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance, generally rental properties first built on or before October 1, 1978.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
